-- Baleshhaa catalogue backup: 3 sections, 14 categories, 14 original SVG media records
-- This script is idempotent, for restoration only. These records already exist in the live Neon database.
BEGIN;
ALTER TABLE app_media DROP CONSTRAINT IF EXISTS app_media_mime_type_check;
ALTER TABLE app_media ADD CONSTRAINT app_media_mime_type_check CHECK (mime_type IN ('image/png','image/jpeg','image/webp','image/svg+xml'));
COMMIT;
